function cleanLines(arr){ if(arr.length && arr[arr.length-1]==='') arr.pop(); return arr; }
function diffLines(aText, bText){
  var a=cleanLines(String(aText).split('\n'));
  var b=cleanLines(String(bText).split('\n'));
  var n=a.length, m=b.length;
  var dp=[]; for(var i=0;i<=n;i++){ dp[i]=new Array(m+1).fill(0); }
  for(var i=n-1;i>=0;i--){ for(var j=m-1;j>=0;j--){ dp[i][j]=(a[i]===b[j])?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]); } }
  var res=[], i=0, j=0;
  while(i<n&&j<m){
    if(a[i]===b[j]){ res.push({type:'eq',a:a[i],b:b[j]}); i++; j++; }
    else if(dp[i+1][j]>=dp[i][j+1]){ res.push({type:'del',a:a[i]}); i++; }
    else { res.push({type:'add',b:b[j]}); j++; }
  }
  while(i<n){ res.push({type:'del',a:a[i]}); i++; }
  while(j<m){ res.push({type:'add',b:b[j]}); j++; }
  return res;
}
function inlineDiff(a, b){
  a=String(a); b=String(b);
  var n=a.length, m=b.length;
  var dp=[]; for(var i=0;i<=n;i++){ dp[i]=new Array(m+1).fill(0); }
  for(var i=n-1;i>=0;i--){ for(var j=m-1;j>=0;j--){ dp[i][j]=(a[i]===b[j])?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]); } }
  var res=[], i=0, j=0;
  while(i<n&&j<m){
    if(a[i]===b[j]){ res.push({type:'eq',t:a[i]}); i++; j++; }
    else if(dp[i+1][j]>=dp[i][j+1]){ res.push({type:'del',t:a[i]}); i++; }
    else { res.push({type:'add',t:b[j]}); j++; }
  }
  while(i<n){ res.push({type:'del',t:a[i]}); i++; }
  while(j<m){ res.push({type:'add',t:b[j]}); j++; }
  return res;
}
function diffStats(diff){ var add=0,del=0,eq=0; diff.forEach(function(d){ if(d.type==='add')add++; else if(d.type==='del')del++; else eq++; }); return {add:add,del:del,eq:eq}; }
function unifiedText(diff, aName, bName){
  aName=aName||'a'; bName=bName||'b';
  var lines=['--- '+aName, '+++ '+bName];
  diff.forEach(function(d){
    if(d.type==='eq') lines.push(' '+d.a);
    else if(d.type==='del') lines.push('-'+d.a);
    else lines.push('+'+d.b);
  });
  return lines.join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { diffLines:diffLines, inlineDiff:inlineDiff, diffStats:diffStats, unifiedText:unifiedText };
}
if (typeof window !== 'undefined') {
  window.DiffForgePure = { diffLines:diffLines, inlineDiff:inlineDiff, diffStats:diffStats, unifiedText:unifiedText };
}
